package net.officefloor.hq.app.voidreason;

/** A void reason as the screen shows it: its text. */
public record VoidReasonResponse(long id, String reason) {

    public static VoidReasonResponse from(VoidReason reason) {
        return new VoidReasonResponse(reason.getId(), reason.getReason());
    }
}
-- A sheet's void reasons: trimmed texts, each on the sheet at most once. While the sheet has any, a claim is voided
-- only with one of them.
CREATE TABLE void_reason (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    reason VARCHAR(200) NOT NULL
);
CREATE UNIQUE INDEX void_reason_sheet_reason ON void_reason (sheet_id, reason);
-- The reason a VOID claim was voided with; null when it was voided without one.
ALTER TABLE claim ADD COLUMN void_reason VARCHAR(200);
-- A sheet's claim templates: a trimmed name (on the sheet at most once; saving it again replaces the template), an
-- amount the claim form accepts and a trimmed note. A claim made from one copies its amount and note at that moment.
CREATE TABLE claim_template (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    name VARCHAR(255) NOT NULL,
    amount DECIMAL(19, 2) NOT NULL,
    note VARCHAR(2000) NOT NULL DEFAULT ''
);
CREATE UNIQUE INDEX claim_template_sheet_name ON claim_template (sheet_id, name);
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../api/submitOnce';
import { HomeMain } from '../../slots/defs/homeMain';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { useVoidReasons, voidReasonsPath, voidReasonsQueryKey, type VoidReason } from './voidreasons';

// The sheet's void reasons, and the entry that adds one. A blank reason, or one already on the list, is refused by
// the server and shows the error beside the entry, which goes as soon as the entry changes.
function VoidReasons() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const reasons = useVoidReasons();
  const [reason, setReason] = useState('');
  const queryClient = useQueryClient();
  const add = useMutation({
    mutationFn: (body: { reason: string }) => postJson<VoidReason>(voidReasonsPath(sheet ?? ''), body, user),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: voidReasonsQueryKey(sheet ?? '') });
      setReason('');
    },
  });
  const submit = useSubmitOnce(add);

  if (!user || !sheet) return null;
  return (
    <section data-testid="void-reasons">
      <h2>Void reasons</h2>
      <ul>
        {(reasons.data ?? []).map((r) => (
          <li key={r.id} data-testid={`void-reason-row-${r.reason}`}>{r.reason}</li>
        ))}
      </ul>
      <form
        data-testid="void-reason-form"
        onSubmit={(e) => {
          e.preventDefault();
          submit({ reason });
        }}
      >
        <input
          data-testid="void-reason-text"
          placeholder="Reason"
          value={reason}
          onChange={(e) => { setReason(e.target.value); add.reset(); }}
        />
        <button type="submit" data-testid="void-reason-add" disabled={add.isPending}>
          Add void reason
        </button>
        {add.isError && (
          <span data-testid="void-reason-error">A void reason must not be blank or already on the list.</span>
        )}
      </form>
    </section>
  );
}

export const contribution = HomeMain.fill({ order: 6.6, Component: VoidReasons });
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { useCurrentSheet } from '../session/session';

/** A sheet's void reason as the store holds it: a trimmed text, on the sheet at most once. While the sheet has any,
 *  a claim is voided only with one of them. */
export type VoidReason = { id: number; reason: string };

export const voidReasonsQueryKey = (sheetId: string) => ['sheet', sheetId, 'void-reasons'] as const;

export const voidReasonsPath = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}/void-reasons`;

/** The sheet's void reasons, in the order they were added. */
export function useVoidReasons() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: voidReasonsQueryKey(sheet ?? ''),
    queryFn: () => getJson<VoidReason[]>(voidReasonsPath(sheet ?? '')),
    enabled: !!sheet,
  });
}

