  const res = await fetch(path, init);
  if (!res.ok) {
    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

// A change sends the signed-in name (`user`) as `X-User`, URI-encoded (a header is Latin-1 only),
// so the server records who made it.
const jsonHeaders = (user?: string): Record<string, string> =>
  user ? { 'Content-Type': 'application/json', 'X-User': encodeURIComponent(user) } : { 'Content-Type': 'application/json' };

export function postJson<T>(path: string, body: unknown, user?: string): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: jsonHeaders(user),
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body?: unknown, user?: string): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: jsonHeaders(user),
    body: body === undefined ? undefined : JSON.stringify(body),
  });
}
import { useRef } from 'react';
import type { UseMutationResult } from '@tanstack/react-query';

// Submits a mutation at most once at a time: a second submit (a double click) before the first has
// answered is dropped, so it stores one record, not two. `isPending` alone is not enough: it only
// disables the button once React has re-rendered, which a fast second click can beat.
export function useSubmitOnce<D, V, C>(mutation: UseMutationResult<D, Error, V, C>) {
  const busy = useRef(false);
  return (variables: V) => {
    if (busy.current) return;
    busy.current = true;
    mutation.reset();
    mutation.mutateAsync(variables).catch(() => undefined).finally(() => { busy.current = false; });
  };
}
